using SoulsFormats;
using System.Collections.Generic;
using System.Linq;
using static SoulsFormats.FFXDLSE;

namespace StudioCore.Editors.FxEditor.Model;

/// <summary>
/// A DLSE effect's FXResourceSet on save (decision §8.6 of the FFX plan, survey §16.1). The five vectors list the
/// models (Param41), textures (Param40), nothing (vector 3), action ids and called effects an effect needs. Vanilla
/// lists are generated by the build tool and often hold more than the effect and its called effects use, but every
/// vanilla list holds every id its own effect uses directly (checked over all DES, DS2 and DS2S effects). Saving keeps
/// that true: the stored lists are kept, and an id the effect uses that its list lacks is appended. A vanilla effect,
/// or one whose ids didn't change, keeps its lists byte for byte.
/// </summary>
public static class FfxResources
{
    /// <summary>The ids an effect uses directly, per vector (index 0–4); 0 (no resource) left out.</summary>
    public static HashSet<int>[] Uses(FXEffect fx)
    {
        var uses = new HashSet<int>[5];
        for (int i = 0; i < 5; i++)
            uses[i] = new HashSet<int>();
        void Param(Param p)
        {
            switch (p)
            {
                case Param41 m: uses[0].Add(m.Unk04); break;
                case Param40 t: uses[1].Add(t.TextureID); break;
                case Param38 a: uses[3].Add(a.ActionID); List(a.ParamList); break;
                case Param37 e: uses[4].Add(e.EffectID); List(e.ParamList); break;
                case Param82 w: Param(w.Param); break;
                case Param84 w: Param(w.Param); break;
            }
        }
        void List(ParamList l)
        {
            foreach (var p in l.Params)
                Param(p);
        }
        List(fx.ParamList1);
        List(fx.ParamList2);
        foreach (var s in fx.StateMap.States)
            foreach (var a in s.Actions)
            {
                uses[3].Add(a.ID);
                List(a.ParamList);
            }
        foreach (var set in uses)
            set.Remove(0);
        return uses;
    }

    public static List<int>[] Vectors(FXEffect fx)
    {
        var rs = fx.ResourceSet;
        return new[] { rs.Vector1, rs.Vector2, rs.Vector3, rs.Vector4, rs.Vector5 };
    }

    /// <summary>
    /// Appends to each resource list of the effect (and of each variant) the ids the effect uses that the list lacks,
    /// in id order, after what is there. Returns how many ids were appended.
    /// </summary>
    public static int AppendMissing(FFXDLSE ffx)
    {
        int appended = 0;
        foreach (var fx in ffx.Effect.Variants?.Select(v => v.Effect) ?? new[] { ffx.Effect })
        {
            var uses = Uses(fx);
            var vectors = Vectors(fx);
            for (int v = 0; v < 5; v++)
                foreach (var id in uses[v].Where(id => !vectors[v].Contains(id)).OrderBy(id => id).ToList())
                {
                    vectors[v].Add(id);
                    appended++;
                }
        }
        return appended;
    }
}
